import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** One row of the `jobs` table, as SQLite returns it. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  /** Epoch milliseconds before which a queued job must not be claimed (retry back-off). */
  run_after: number;
  created_at: string;
  updated_at: string;
}

/**
 * Opens the SQLite database shared by the server and worker processes and makes sure the schema exists.
 * Both processes call this; `CREATE ... IF NOT EXISTS` is safe to run from either.
 */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(`
    CREATE TABLE IF NOT EXISTS jobs (
      seq INTEGER PRIMARY KEY AUTOINCREMENT,
      id TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL,
      input TEXT NOT NULL,
      steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL,
      attempts INTEGER NOT NULL DEFAULT 0,
      completed INTEGER NOT NULL DEFAULT 0,
      result_output TEXT,
      error TEXT,
      run_after INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS jobs_claim ON jobs (status, run_after, seq);
    CREATE TABLE IF NOT EXISTS idempotency (
      key TEXT PRIMARY KEY,
      payload TEXT NOT NULL,
      job_id TEXT NOT NULL REFERENCES jobs (id)
    );
    CREATE TABLE IF NOT EXISTS heartbeat (
      name TEXT PRIMARY KEY,
      ts INTEGER NOT NULL
    );
  `);
  return db;
}

/** Converts a row to the public job representation defined in TASK.md. */
export function jobToJson(r: JobRow) {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.completed, total: r.steps },
    result: r.status === 'completed' ? { output: r.result_output } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

/** Typed wrapper for `StatementSync.get`, whose return type is a generic record. */
export function one<T>(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): T | undefined {
  return db.prepare(sql).get(...params) as unknown as T | undefined;
}

/** Typed wrapper for `StatementSync.all`. */
export function many<T>(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): T[] {
  return db.prepare(sql).all(...params) as unknown as T[];
}

